namespace OpenTPW;

/// <summary>
/// Approximation register of guest arrivals (docs/GUESTS.md, "Arrivals"). Each entry is tagged
/// <c>[APPROX:ARRIVAL-NNN]</c> at its code site; the arrival rule itself is traced from the Mac binary.
/// </summary>
public static class ArrivalApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("ARRIVAL-001", "VEHICLE STOP: the arrival update drives the level's bus, seaplane or Ferry as tp.exe 0x4CF3E0 does (dispatch by group size 0x51A2F0, guests only at status 2, the vehicle's own script for the drive), and a leaving guest walks the cell map from the gate's crossing cell as the original's states 19 to 21 do (0x500AD0 waits for the vehicle's status, 0x51A760, then a world draw picks one of the four cells around BusStopA, 0x4D8650, and two more the point in it; 0x500BD0 re-picks at status 1 to 3 off the vehicle kind's two cells and boards the guest heading its cell's thing list at status 4; the pick-up test 0x51A9D0 reads those heads), but a cell's thing list is OpenTPW's occupant list (WALK-003), and a guest whose stop cell no route reaches (a lane the map leaves untyped, WALK-008) or that was refused at the booth keeps OpenTPW's lane walk, where it waits at its lane's first cell and boards at status 4, one per stop cell and turn in update order; the arrival update runs before the guest updates of a turn, where the original runs it after the thing sweep (end of 0x516380); and an imported original save starts with no vehicle at work (its +0x1DA72A word is not decoded)"),
		("ARRIVAL-003", "POINTS: the counts-test (tp.exe 0x4DD920) and the kind filter (Info.WhichUIType 0 or 2, 0x4C8240) are applied, the coaster test 0x441970 as CoasterRide.AcceptsGuests and the kart and water track word +0x2C as BumpController.IsTrackValid. Residuals: OpenTPW's coaster test also needs 3 track samples (its not-the-coaster-being-edited term, 0x790FEC, is CoasterRide.BeingEdited), and a kart or water ride's track word is false before its first circuit walk where the original's constructor sets 1 (0x4DB0DF); a coaster imported from an original save has no controller (its track is not imported, SAVE-920 to SAVE-923), so it gives no points where the original counts it"),
		("ARRIVAL-005", "FIRST PURCHASE ON IMPORT: an object imported from an original save sets its type's first-purchase turn to the import turn while it is 0; the original restores every type's record (+0x1C first purchase, +0x18 copies) verbatim from the save's object-control block (the world loader 0x5179C0 reads it with 0x4D3AA0 at 0x5181E7: 150 records of 32 bytes, the count and the search key), adds zeroed records for types missing from it (0x4D3E00 after the load) and stamps a turn only into a record still at 0 (0x4DB690); OpenTPW keeps that block opaque. Fixed items of a new park agree: the park gates and traffic lights are built after the turn is set to 0 (0x515865)"),
		("ARRIVAL-006", "BOOTH WAIT: an expensive verdict holds the guest for 50 + R % 50 state-4 updates, one per executed park turn, and the verdict runs again on the turn after (tp.exe 0x4FF9D0), N + 1 turns in all; OpenTPW counts those N + 1 park turns too, but its fixed-step loop drops none, where the original's loop can drop at most 3 per pass (0x54F680); a closed park's state 3 (0x4FF966) first counts any remaining wait +0x200 down, one per guest update, before it sends the guest home, where OpenTPW sends it home at once (the wait is 0 on both of OpenTPW's paths into it: a guest arriving at the booth and one that has just paid after its wait ran out); and the booth's first verdict follows the walk to it after TicketBoothSeconds rather than at the next update"),
	};
